export const SLOTS=['RMB','Q','E','R'];
export const spellId=(path,slot)=>path+'-spell-'+slot;
export const TALENT_NODES=[];
for(const [path,slots] of Object.entries(TREES))for(const slot of SLOTS){
 const [name,description,a,a2,b,b2]=slots[slot],root=spellId(path,slot);
 TALENT_NODES.push({id:root,path,ability:slot,tier:0,type:'spell',name,description,effects:[],parents:[]});
 // Oct 16 (user): augments form a small tree again. Tier 1 (first two) needs the spell; tier 2 (last two) needs a tier-1 augment of that spell.
 [a,a2,b,b2].forEach((n,i)=>{
  // Escape belongs to Blink (SPACE) even though it sits in the Static Guard tree.
  const effects=n.stat?[{stat:n.stat,value:n.value,ability:n.id==='escape'?'SPACE':slot}]:[];
  if(n.id==='bloodDominion')effects.push({stat:'duration',value:-.20,ability:'R'});
  if(n.id==='crimsonSanctuary')effects.push({stat:'cooldown',value:-.25,ability:'Q'});
  TALENT_NODES.push({id:n.id,path,ability:slot,tier:i<2?1:2,type:'behavior',name:n.name,description:n.description,effects,parents:i<2?[root]:[a.id,a2.id],root});
 });
}
